#include <string>
#include <map>
#include <tuple>
using namespace std;

class Solution {
public:
    int countBalanced(string low, string high) {
        const int MOD = 1000000007;
        auto countUpTo = [&](const string& s) -> int {
            map<tuple<int, int, bool, bool>, int> memo;
            auto dfs = [&](auto& self, int i, int diff, bool is_tight, bool started) -> int {
                if (i == (int)s.size()) return (started && diff == 0) ? 1 : 0;
                auto key = make_tuple(i, diff, is_tight, started);
                if (memo.count(key)) return memo[key];
                int limit = is_tight ? (s[i] - '0') : 9;
                int res = 0;
                for (int d = 0; d <= limit; d++) {
                    bool next_tight = is_tight && (d == limit);
                    if (!started && d == 0) {
                        res = (res + self(self, i + 1, diff, next_tight, false)) % MOD;
                    } else {
                        int next_diff = (i % 2 == 0) ? diff + d : diff - d;
                        res = (res + self(self, i + 1, next_diff, next_tight, true)) % MOD;
                    }
                }
                return memo[key] = res;
            };
            return dfs(dfs, 0, 0, true, false);
        };
        auto decStr = [](string s) -> string {
            int n = s.size();
            for (int i = n - 1; i >= 0; i--) {
                if (s[i] > '0') {
                    s[i]--;
                    break;
                }
                s[i] = '9';
            }
            int start = 0;
            while (start < n - 1 && s[start] == '0') start++;
            return s.substr(start);
        };
        int highCount = countUpTo(high);
        int lowCount = countUpTo(decStr(low));
        return (highCount - lowCount + MOD) % MOD;
    }
};

import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;

    public int countBalanced(String low, String high) {
        int highCount = countUpTo(high);
        int lowCount = countUpTo(decrement(low));
        return (highCount - lowCount + MOD) % MOD;
    }

    private int countUpTo(String s) {
        Map<String, Integer> memo = new HashMap<>();
        return dfs(s, 0, 0, true, false, memo);
    }

    private int dfs(String s, int i, int diff, boolean isTight, boolean started, Map<String, Integer> memo) {
        if (i == s.length()) return (started && diff == 0) ? 1 : 0;
        String key = i + "," + diff + "," + isTight + "," + started;
        if (memo.containsKey(key)) return memo.get(key);
        int limit = isTight ? (s.charAt(i) - '0') : 9;
        int res = 0;
        for (int d = 0; d <= limit; d++) {
            boolean nextTight = isTight && (d == limit);
            if (!started && d == 0) {
                res = (res + dfs(s, i + 1, diff, nextTight, false, memo)) % MOD;
            } else {
                int nextDiff = (i % 2 == 0) ? diff + d : diff - d;
                res = (res + dfs(s, i + 1, nextDiff, nextTight, true, memo)) % MOD;
            }
        }
        memo.put(key, res);
        return res;
    }

    private String decrement(String s) {
        char[] arr = s.toCharArray();
        for (int i = arr.length - 1; i >= 0; i--) {
            if (arr[i] > '0') {
                arr[i]--;
                break;
            }
            arr[i] = '9';
        }
        int start = 0;
        while (start < arr.length - 1 && arr[start] == '0') start++;
        return new String(arr, start, arr.length - start);
    }
}

